public class BabylonScales : MonoBehaviour
{
	private static GameObject prefab;

	private Animator anim;

	[HideInInspector]
	public Attack attack;

	private CircleCollider2D attackCollider;

	private float attackRadius = 5f;

	private ChaosQuickStopwatch attackStopwatch = new ChaosQuickStopwatch(0.25f);

	private bool attackCompleted;

	private float lerpValue;

	private bool targetHit;

	public float cdrValue = 2f;

	public float buffDuration = 2.25f;

	public float buffSpeed = 0.75f;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/BabylonScales.prefab"));

	private void Awake()
	{
		anim = GetComponent<Animator>();
		this.attack = transform.Find("Attack").GetComponent<Attack>();
		Attack attack = this.attack;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		Attack attack2 = this.attack;
		attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		attackCollider = this.attack.transform.GetComponent<CircleCollider2D>();
	}

	private void Start()
	{
		PoolManager.GetPoolItem<DustEmitter>().EmitCircle(200, 2f, 25f, 1f, transform.position);
		attackStopwatch.IsRunning = true;
		attackCollider.enabled = true;
		attackCompleted = false;
	}

	private void FixedUpdate()
	{
		if (!attackCompleted)
		{
			lerpValue = attackStopwatch.TimePercentage;
			attackCollider.radius = Mathf.Lerp(0.5f, attackRadius, lerpValue);
			attack.knockbackMultiplierOverride = Mathf.Lerp(50f, 15f, lerpValue);
			if (!(lerpValue < 1f))
			{
				attackCollider.enabled = false;
				attackCompleted = true;
				UnityEngine.Object.Destroy(gameObject, 1f);
			}
		}
	}

	private void OnTargetHit(Entity givenEnt)
	{
		if (givenEnt == null || givenEnt is Destructible)
		{
			return;
		}
		if (givenEnt.health != null && !givenEnt.health.ignoreSlow.CurrentValue)
		{
			ApplyDoT(givenEnt, givenStatus: false);
		}
		if (targetHit)
		{
			return;
		}
		targetHit = true;
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (!(player == null) && Vector2.Distance(player.transform.position, transform.position) <= attackRadius)
			{
				ApplyDoT(player, givenStatus: true);
				player.cooldownManager.LowerAllCoolDownTimers(cdrValue, player);
			}
		}
	}

	private void ApplyDoT(Entity givenEntity, bool givenStatus)
	{
		if (givenEntity.dotManager != null)
		{
			givenEntity.dotManager.AddDot(new BabylonScalesDotEffect(givenEntity, buffDuration, buffSpeed, givenStatus));
		}
	}
}

