public class NegDashState : BaseDashState
{
	public bool useCastBar = true;

	public float chargeTime = 0.25f;

	public int chargeStopwatchID;

	public bool chargeStarted;

	public bool isCharged;

	public int postStopwatchID;

	private bool autoReleaseHold;

	private bool dashExecuted;

	public override string OnHoldAnimStr => parent.GSlamAnimStr;

	public NegDashState(string skillID, FSM fsm, Player player)
		: base(skillID, fsm, player)
	{
		isHoldSkill = true;
		startCooldownOnEnter = false;
		playSFX = false;
		showEffects = false;
		SetAnimTimes(0f, 0f, 0.3f, 0.55f, 0.75f);
	}

	public override void OnEnter()
	{
		base.OnEnter();
		holdReleased = false;
		chargeStarted = false;
		isCharged = false;
		dashExecuted = false;
	}

	public override void Update()
	{
		if (cooldownReady && !holdReleased)
		{
			HandleHoldButton();
			if (!holdReleased)
			{
				return;
			}
		}
		base.Update();
	}

	public override void HandleHoldButton()
	{
		if (!holdReleased)
		{
			holdReleased = !parent.inputDevice.GetButton("Skill" + skillSlot);
		}
		if (!finishedDashing)
		{
			return;
		}
		if (!chargeStarted)
		{
			chargeStarted = true;
			chargeStopwatchID = ChaosStopwatch.Begin(chargeTime);
			if (useCastBar)
			{
				parent.hud.castBar.StartCast(chargeStopwatchID, givenStatus: true);
			}
			PlayChargeEffects();
		}
		inputVector = GetInputVector(faceInputVector: true, ChaosInputDevice.lockControllerAim ? true : false);
		parent.anim.PlayDirectional(OnHoldAnimStr, -1, animHoldTime);
		if (!isCharged)
		{
			isCharged = ChaosStopwatch.Check(chargeStopwatchID);
			if (isCharged)
			{
				PlayChargeEffects();
				postStopwatchID = ChaosStopwatch.Begin(chargeTime);
				holdReleased = autoReleaseHold;
			}
		}
		else
		{
			HandlePostStopwatch();
		}
	}

	public override void ExitTransition()
	{
		if (chargeStarted)
		{
			if (!dashExecuted)
			{
				ExecuteDash();
			}
			else
			{
				ExitToSkillOrRunOrIdle();
			}
		}
		else
		{
			base.ExitTransition();
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		if (chargeStarted && useCastBar)
		{
			parent.hud.castBar.EndCast();
		}
	}

	public virtual void PlayChargeEffects()
	{
	}

	public virtual void HandlePostStopwatch()
	{
		if (ChaosStopwatch.Check(postStopwatchID))
		{
			postStopwatchID = ChaosStopwatch.Begin(chargeTime);
			PlayChargeEffects();
		}
	}

	public virtual void ExecuteDash()
	{
		dashExecuted = true;
		parent.hud.castBar.EndCast();
		parent.anim.PlayDirectional(OnHoldAnimStr, -1, animExecTime);
	}
}

